const BASE_URL = 'https://merchant.arionpay.com';
const PUBLIC_KEY = process.env.ARIONPAY_PUBLIC_KEY; // pk_...
const SECRET_KEY = process.env.ARIONPAY_SECRET_KEY; // sk_...

const path = '/api/v1/invoices';
const body = JSON.stringify({
  "amount": "49.00",
  "currency": "USD",
  "orderId": "order-1001",
  "description": "Order #1001",
  "successUrl": "https://shop.example.com/thanks",
  "cancelUrl": "https://shop.example.com/cart",
  "test": true
});

const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = crypto
  .createHmac('sha256', SECRET_KEY)
  .update(`${timestamp}.${body}`)
  .digest('hex');

const res = await fetch(BASE_URL + path, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': PUBLIC_KEY,
    'x-timestamp': timestamp,
    'x-signature': signature,
  },
  body, // send exactly the string you signed
});
const data = await res.json();
if (!res.ok) throw new Error(`${res.status}: ${data.error}`);
console.log('Invoice', data.id, '- send the customer to', data.invoice_url);
