```js
import crypto from 'node:crypto';

// rawBody: the request body exactly as received (a string or Buffer), before JSON parsing
function verifyArionPay(rawBody, header, webhookSecret) {
  const parts = Object.fromEntries(header.split(',').map((p) => p.split('=')));
  const age = Math.abs(Date.now() / 1000 - Number(parts.t));
  if (!parts.t || !parts.v1 || age > 300) return false; // reject old or malformed signatures
  const expected = crypto.createHmac('sha256', webhookSecret).update(`${parts.t}.${rawBody}`).digest('hex');
  const a = Buffer.from(expected, 'hex'), b = Buffer.from(parts.v1, 'hex');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
```
